#!/usr/bin/env Rscript
# Final step of run_all.R: build the main-text table of the cmdstanr studies from their
# summaries, collect all result macros into generated/results.tex and list the
# generated files the LaTeX sources expect.
BO_ROOT <- local({a <- commandArgs(FALSE); f <- sub("^--file=", "", a[grep("^--file=", a)])
  if (length(f)) dirname(dirname(normalizePath(f))) else if (dir.exists("analysis")) "analysis" else ".."})
for (f in c("common.R", "paper.R")) source(file.path(BO_ROOT, "R", f))

## Main-text table of the Stan studies (rows from scripts 10-12, when they have been run)
rd <- function(n) { f <- file.path(results_dir, paste0(n, ".rds")); if (file.exists(f)) readRDS(f) else NULL }
es <- rd("stan_eight_schools_summary"); rg <- rd("stan_regression_dimension_summary"); mx <- rd("stan_mixture_summary")
rows <- list(); grp <- character(0)
add <- function(study, conf, x) {
  rows[[length(rows) + 1L]] <<- c(study, conf, x$S, fx(x$coverage, 3), fx(x$rmse_over_mcse, 2), fint(x$med_n_ov),
                                  fx(x$med_I, 2), fx(x$med_n_ovP, 1), fx(100 * x$flag_overlap, 0), fx(100 * x$flag_any_failure, 0))
  grp <<- c(grp, study)
}
if (!is.null(es)) for (i in seq_len(nrow(es))) {
  x <- es[i, ]
  add(if (i == 1) "eight schools (NUTS)" else "", sprintf("%s, $\\delta=%s$", x$model, format(x$adapt_delta)), x)
}
if (!is.null(rg)) { k <- rg[rg$dim %in% range(rg$dim), ]
  for (i in seq_len(nrow(k))) add(if (i == 1) "regression (\\texttt{mcycle})" else "", sprintf("dimension %d, %s", k$dim[i], k$arm[i]), k[i, ]) }
if (!is.null(mx)) for (i in seq_len(nrow(mx))) {
  x <- mx[i, ]; x$S <- 4000L
  lab <- c("m = 3, random inits" = "$m=3$, random initial values", "m = 5, inits 3:1" = "$m=5$, initial values 3:1",
           "m = 5, inits 4:0 (one mode)" = "$m=5$, initial values 4:0")
  add(if (i == 1) "two-mode mixture" else "", lab[[x$config]], x)
}
if (length(rows)) {
  emit_table("tab_stan", do.call(rbind, rows), groups = group_ends(cumsum(grp != "")),
             spec = "llrcccccrr",
             header = "Study & configuration & $S$ & coverage & RMSE/MCSE & med $\\neffhat$ & med $\\Ihat$ & med $\\neffPhat$ & overlap flag & failure flags\\\\")
}

## Replication counts actually used (from the logs written by every script) and provenance.
# (replications_used.csv is this script's own output: reading it back would duplicate every row)
logs <- list.files(results_dir, pattern = "^replications_.*[.]csv$", full.names = TRUE)
logs <- logs[basename(logs) != "replications_used.csv"]
reps_used <- if (length(logs)) do.call(rbind, lapply(logs, utils::read.csv, stringsAsFactors = FALSE)) else NULL
final <- !is.null(reps_used) && all(reps_used$BO_SCALE == 1) && !BO_QUICK
if (!is.null(reps_used)) {
  reps_used <- reps_used[order(reps_used$script, reps_used$key), ]
  save_table(reps_used, "replications_used")
  tex_key <- function(k) gsub("([_$&%#])", "\\\\\\1", sub("^REPS\\$", "", k))
  emit_table("tab_replications", cbind(gsub("_", "\\\\_", reps_used$script), paste0("\\texttt{", tex_key(reps_used$key), "}"),
                                       gsub("/", ", ", reps_used$specified), gsub("/", ", ", reps_used$used)),
             spec = "lllr", header = "Script & key in \\texttt{analysis/config.R} & specified & used\\\\")
}
git <- function(args) tryCatch(suppressWarnings(system2("git", c("-C", dirname(BO_ROOT), args), stdout = TRUE, stderr = FALSE)),
                               error = function(e) character(0))
commit <- git(c("rev-parse", "--short", "HEAD")); tag <- git(c("describe", "--tags", "--always", "--dirty"))
prov <- c("% generated by analysis/supplement/S99_assemble.R -- do not edit",
          sprintf("\\resdef{prov.commit}{%s}", if (length(commit)) commit else "unversioned"),
          sprintf("\\resdef{prov.tag}{%s}", if (length(tag)) gsub("_", "\\\\_", tag) else "unversioned"),
          sprintf("\\resdef{prov.date}{%s}", format(Sys.Date())),
          sprintf("\\resdef{prov.R}{%s}", paste(R.version$major, R.version$minor, sep = ".")),
          sprintf("\\resdef{prov.bs}{%s}", as.character(utils::packageVersion("bridgesampling"))),
          sprintf("\\resdef{prov.final}{%s}", if (final) "1" else "0"))
writeLines(prov, file.path(gen_dir, "results_zz_provenance.tex"))
if (!final) msg("NOT FINAL: some results come from a scaled or quick run (BO_SCALE < 1 or BO_QUICK); prov.final is 0.")

## results.tex
parts <- sort(list.files(gen_dir, pattern = "^results_.*[.]tex$", full.names = TRUE))
writeLines(c("% generated by analysis/supplement/S99_assemble.R -- do not edit", unlist(lapply(parts, readLines))),
           file.path(gen_dir, "results.tex"))
expected <- c(paste0(c(
  # main text
  "tab_OC",
  # supplement
  "tab_ES_top", "tab_ES_bottom", "tab_ES_rwm2x2", "tab_E1_top", "tab_E1_bottom", "tab_E7", "tab_E6", "tab_unbal",
  "tab_OC_pooled", "tab_EB", "tab_NP", "tab_ADV", "tab_ADV_check", "tab_E2", "tab_FA", "tab_E3", "tab_E8", "tab_E9_top",
  "tab_E9_bottom", "tab_LRV", "tab_regen", "tab_E4", "tab_prop", "tab_E4c", "tab_E5", "tab_R1", "tab_R2", "tab_stan_es",
  "tab_stan_reg", "tab_stan_mix", "tab_bench", "tab_bf", "tab_detect", "tab_cost", "tab_rerun", "tab_replications"), ".tex"),
  "fig_universality.pdf", "fig_mcmc.pdf", "fig_conditional.pdf", "fig_two_point.pdf", "fig_bench.pdf", "fig_bf.pdf", "fig_es_qq.pdf", "results.tex")
have <- file.exists(file.path(gen_dir, expected))
# result keys that the LaTeX sources use but no script defined (they would print as ??)
defined <- sub("^\\\\resdef\\{([^}]*)\\}.*$", "\\1", grep("^\\\\resdef\\{", readLines(file.path(gen_dir, "results.tex")), value = TRUE))
srcs <- Filter(nzchar, strsplit(Sys.getenv("BO_TEX", ""), ":", fixed = TRUE)[[1]])   # LaTeX files to check, if any
used <- unlist(lapply(srcs[file.exists(srcs)], function(f) {
  x <- sub("(^|[^\\\\])%.*$", "\\1", readLines(f, warn = FALSE))   # drop comments
  unlist(regmatches(x, gregexpr("\\\\res\\{[^}]*\\}", x)))
}))
missing_keys <- sort(setdiff(unique(sub("^\\\\res\\{(.*)\\}$", "\\1", used)), defined))
writeLines(c("Output files:",
             sprintf("  [%s] %s", ifelse(have, "x", " "), expected),
             sprintf("Final run (BO_SCALE = 1, no BO_QUICK): %s", if (final) "yes" else "NO"),
             sprintf("Result keys used by the LaTeX sources in BO_TEX but not defined: %s",
                     if (length(missing_keys)) paste(missing_keys, collapse = ", ") else "none")), file.path(gen_dir, "MANIFEST.txt"))
msg(sum(have), "of", length(expected), "expected files present in generated/ (see MANIFEST.txt)")
if (length(missing_keys)) {
  msg(length(missing_keys), "result key(s) used by the sources are undefined and will print as ??:",
      paste(missing_keys, collapse = ", "))
  if (final) stop("undefined result keys in a final run (see MANIFEST.txt)")
}
